If you’re learning C++ file I/O, I can show you how to read a normal text file. For example:

#include <iostream>
#include <fstream>
#include <string>

int main() {
    std::ifstream file("sample.txt");
    if (!file) {
        std::cerr << "Cannot open file\n";
        return 1;
    }
    std::string line;
    while (std::getline(file, line)) {
        std::cout << line << '\n';
    }
    return 0;
}

